const A4 = { width: 11906, height: 16838 };
const MARGINS = { top: 1134, right: 850, bottom: 1134, left: 1701, header: 567, footer: 567 };
const CONTENT_WIDTH = A4.width - MARGINS.left - MARGINS.right;
const FONT = 'Times New Roman';
const BLACK = '000000';
const BLUE = '1F4E79';
const LIGHT_BLUE = 'D9EAF7';
const VERY_LIGHT_BLUE = 'EEF5FA';
const LIGHT_GRAY = 'F2F2F2';
const WHITE = 'FFFFFF';

const thin = { style: BorderStyle.SINGLE, size: 4, color: '8A8A8A' };
const borders = { top: thin, bottom: thin, left: thin, right: thin, insideHorizontal: thin, insideVertical: thin };

function run(text, opts = {}) {
  return new TextRun({ text, font: FONT, size: opts.size || 28, bold: !!opts.bold, italics: !!opts.italics, color: opts.color || BLACK });
}

function p(text = '', opts = {}) {
  const children = Array.isArray(text) ? text : [run(text, opts)];
  return new Paragraph({
    children,
    alignment: opts.alignment || AlignmentType.JUSTIFIED,
    spacing: opts.spacing || { line: 360, after: opts.after ?? 120 },
    indent: opts.noIndent ? undefined : { firstLine: 709 },
    keepNext: !!opts.keepNext,
    pageBreakBefore: !!opts.pageBreakBefore,
  });
}

function center(text, opts = {}) {
  return p([run(text, opts)], { alignment: AlignmentType.CENTER, noIndent: true, spacing: opts.spacing || { line: 360, after: opts.after ?? 120 }, keepNext: opts.keepNext });
}

function h1(text, pageBreakBefore = false) {
  return new Paragraph({
    heading: HeadingLevel.HEADING_1,
    children: [run(text, { bold: true })],
    pageBreakBefore,
  });
}

function h2(text) {
  return new Paragraph({ heading: HeadingLevel.HEADING_2, children: [run(text, { bold: true })] });
}

function h3(text) {
  return new Paragraph({ heading: HeadingLevel.HEADING_3, children: [run(text, { bold: true })] });
}

function bullet(text, level = 0) {
  return new Paragraph({
    numbering: { reference: 'bullets', level },
    children: [run(text)],
    alignment: AlignmentType.JUSTIFIED,
    spacing: { line: 360, after: 80 },
  });
}

function req(id, text) {
  return p([run(id + '. ', { bold: true }), run(text)], { noIndent: true, spacing: { line: 360, after: 100 } });
}

function caption(text) {
  return p([run(text, { italics: true, size: 24 })], { noIndent: true, alignment: AlignmentType.LEFT, spacing: { line: 280, before: 120, after: 80 }, keepNext: true });
}

function cell(content, width, opts = {}) {
  const children = Array.isArray(content)
    ? content.map(v => v instanceof Paragraph ? v : p(String(v), { noIndent: true, spacing: { line: 240, after: 40 } }))
    : [p(String(content), { noIndent: true, spacing: { line: 240, after: 40 } })];
  return new TableCell({
    width: { size: width, type: WidthType.DXA },
    borders,
    shading: opts.fill ? { fill: opts.fill, type: ShadingType.CLEAR } : undefined,
    verticalAlign: opts.verticalAlign || VerticalAlign.TOP,
    margins: { top: 80, bottom: 80, left: 100, right: 100 },
    children,
  });
}

function cellText(text, opts = {}) {
  return new Paragraph({
    children: [run(text, { bold: opts.bold, size: opts.size || 22, color: opts.color || BLACK })],
    alignment: opts.alignment || AlignmentType.LEFT,
    spacing: { line: 240, after: 20 },
  });
}

function table(headers, rows, widths, opts = {}) {
  if (widths.reduce((a, b) => a + b, 0) !== CONTENT_WIDTH) throw new Error('Table widths must equal content width');
  const headerRow = new TableRow({
    tableHeader: true,
    cantSplit: true,
    children: headers.map((v, i) => cell([cellText(v, { bold: true, color: WHITE, alignment: AlignmentType.CENTER })], widths[i], { fill: BLUE, verticalAlign: VerticalAlign.CENTER })),
  });
  const bodyRows = rows.map((row, ri) => new TableRow({
    cantSplit: true,
    children: row.map((v, i) => {
      const paras = Array.isArray(v) ? v.map(x => x instanceof Paragraph ? x : cellText(String(x))) : [cellText(String(v))];
      return cell(paras, widths[i], { fill: opts.band && ri % 2 ? VERY_LIGHT_BLUE : undefined });
    }),
  }));
  return new Table({ width: { size: CONTENT_WIDTH, type: WidthType.DXA }, columnWidths: widths, rows: [headerRow, ...bodyRows] });
}

function note(text) {
  return new Table({
    width: { size: CONTENT_WIDTH, type: WidthType.DXA },
    columnWidths: [CONTENT_WIDTH],
    rows: [new TableRow({
      cantSplit: true,
      children: [new TableCell({
        width: { size: CONTENT_WIDTH, type: WidthType.DXA },
        borders: { top: { ...thin, color: BLUE }, bottom: { ...thin, color: BLUE }, left: { ...thin, color: BLUE }, right: { ...thin, color: BLUE } },
        shading: { fill: LIGHT_BLUE, type: ShadingType.CLEAR },
        margins: { top: 120, bottom: 120, left: 140, right: 140 },
        children: [p([run('Принцип: ', { bold: true, size: 24, color: BLUE }), run(text, { size: 24 })], { noIndent: true, spacing: { line: 300, after: 0 } })],
      })],
    })],
  });
}

